using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class BOFinal {
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty)throw new Exception("Saved edit required");string r=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));string h=r+"/SourceAssets/B2_OperationsRebuild/",o=r+"/Docs/Review/2026-11-10_B2_Operations/";var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var ids=all.Select(t=>GlobalObjectId.GetGlobalObjectIdSlow(t).ToString()).ToHashSet();var old=JArray.Parse(File.ReadAllText(h+"before.json"));var root=GameObject.Find("B2_OperationsLayout");var lights=s.GetRootGameObjects().Where(g=>g.name.StartsWith("B2_")).SelectMany(g=>g.GetComponentsInChildren<Light>()).ToArray();var meshes=root.GetComponentsInChildren<MeshFilter>().Where(m=>!m.name.Contains("Collision")&&m.GetComponent<MeshRenderer>()?.enabled==true).ToArray();var stats=new{scene=s.path,saved=!s.isDirty,rooms=root.transform.childCount,originalTransforms=old.Count,missingOriginal=old.Where(t=>!ids.Contains((string)t["id"])).Select(t=>(string)t["name"]).ToArray(),lights=lights.Length,whiteDirect=lights.Count(l=>l.color.g>.55f&&l.color.b>.55f),newLodGroups=root.GetComponentsInChildren<LODGroup>().Length,missingMeshes=meshes.Where(m=>!m.sharedMesh).Select(m=>m.name).ToArray(),missingMaterials=root.GetComponentsInChildren<MeshRenderer>().Where(m=>m.sharedMaterials.Any(a=>!a)).Select(m=>m.name).ToArray(),controllers=root.GetComponentsInChildren<MonoBehaviour>().Length,reflections=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<ReflectionProbe>()).Count()};File.WriteAllText(o+"final_state.json",JsonConvert.SerializeObject(stats,Formatting.Indented));File.WriteAllText(h+"unity_as_built.json",JsonConvert.SerializeObject(root.GetComponentsInChildren<Transform>().Where(t=>t.name.Contains("_Ops_")).Select(t=>new{t.name,parent=t.parent.name,position=new[]{t.position.x,t.position.y,t.position.z},local=new[]{t.localPosition.x,t.localPosition.y,t.localPosition.z},yaw=t.localEulerAngles.y}),Formatting.Indented));return stats;}
}
